SELECT CASE WHEN total = 0 THEN 0 ELSE (100.0 * good) / total END AS percentage
FROM (
  SELECT
    (SELECT COUNT(DISTINCT player_api_id) FROM Player WHERE height < 180) AS total,
    (SELECT COUNT(DISTINCT pa.player_api_id)
     FROM Player_Attributes pa
     JOIN Player p ON p.player_api_id = pa.player_api_id
     WHERE p.height < 180 AND pa.overall_rating > 70
    ) AS good
);

answer_sql:
SELECT CASE WHEN total = 0 THEN 0 ELSE (100.0 * good) / total END AS percentage
FROM (
  SELECT
    (SELECT COUNT(DISTINCT player_api_id) FROM Player WHERE height < 180) AS total,
    (SELECT COUNT(DISTINCT pa.player_api_id)
     FROM Player_Attributes pa
     JOIN Player p ON p.player_api_id = pa.player_api_id
     WHERE p.height < 180 AND pa.overall_rating > 70
    ) AS good
);

