SELECT AVG(CASE WHEN LOWER(sc.name) = 'no skin colour' THEN 1.0 ELSE 0 END) AS average_no_skin
FROM superhero s
LEFT JOIN skin_colour sc ON s.skin_colour_id = sc.id;

SELECT AVG(CASE WHEN LOWER(c.colour) = 'no skin colour' THEN 1.0 ELSE 0 END) AS average_no_skin
FROM superhero s
LEFT JOIN colour c ON s.skin_colour_id = c.id;

answer_sql:
