SELECT CASE WHEN total_female=0 THEN 0 ELSE ROUND((abnormal_female*100.0)/total_female,2) END AS percentage
FROM (
  SELECT
    (SELECT COUNT(*) FROM Patient WHERE SEX='F') AS total_female,
    (SELECT COUNT(DISTINCT l.ID) FROM Laboratory l JOIN Patient p ON l.ID=p.ID WHERE p.SEX='F' AND l.UA>6.5) AS abnormal_female
);

SELECT CASE WHEN total_female=0 THEN 0 ELSE ROUND((abnormal_female*100.0)/total_female,2) END AS percentage
FROM (
  SELECT
    (SELECT COUNT(*) FROM Patient WHERE SEX='F') AS total_female,
    (SELECT COUNT(DISTINCT p.ID)
     FROM Laboratory l
     JOIN Patient p ON l.ID = p.ID
     WHERE p.SEX='F' AND (l.UA < 2.4 OR l.UA > 6.0)
    ) AS abnormal_female
);
